import{_ as p,a0 as o,w as r,s as u,ao as e,I as i,x as a,a1 as n,A as l}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"如何在 Ubuntu 中安装具体指定的软件包版本 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Ubuntu 中安装具体指定的软件包版本 | LCTT (202206) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Ubuntu 中安装具体指定的软件包版本 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Ubuntu 中安装具体指定的软件包版本 | LCTT (202206) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202206/20220518 Install Specific Package Version With Apt Command in Ubuntu","title":"如何在 Ubuntu 中安装具体指定的软件包版本","tag":"202206","desc":""},"relativePath":"202206/20220518 Install Specific Package Version With Apt Command in Ubuntu.md","filePath":"[post].md"}'),d={name:"202206/20220518 Install Specific Package Version With Apt Command in Ubuntu.md"};function h(b,s,g,k,c,m){const t=o("Link");return r(),u("div",null,[s[25]||(s[25]=e('<h1 id="如何在-ubuntu-中安装具体指定的软件包版本" tabindex="-1">如何在 Ubuntu 中安装具体指定的软件包版本 <a class="header-anchor" href="#如何在-ubuntu-中安装具体指定的软件包版本" aria-label="Permalink to “如何在 Ubuntu 中安装具体指定的软件包版本”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202206/26/145335zcrpducpup4p2ugy.jpg" alt=""></p><p>在 Ubuntu 中想安装一个软件包的一个特别指定的版本？你可以通过下面的方式来轻松地完成：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt install package_name=package_version</span></span></code></pre></div><p>你如何知道某个软件包有哪些可用的版本？可以使用这个命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>apt list --all-versions package_name</span></span></code></pre></div><p>在下面的屏幕截屏中，你可以看到，我有两个可用的 VLC 版本，我使用命令来安装较旧的版本：</p><p><img src="https://itsfoss.com/wp-content/uploads/2022/05/install-specific-versions-apt-ubuntu.png" alt="install specific versions apt ubuntu"></p><p>听起来像一个简单的任务，对吧？但是事情并非看起来那么简单。这里有一些不确定是否会出现，但是可能会涉及的东西。</p><p>这篇教程将涵盖使用 <code>apt</code> 或 <code>apt-get</code> 命令来安装一个具体指定的程序的版本的所有的重要的方面。</p><h3 id="安装一个具体指定版本的程序需要知道的事" tabindex="-1">安装一个具体指定版本的程序需要知道的事 <a class="header-anchor" href="#安装一个具体指定版本的程序需要知道的事" aria-label="Permalink to “安装一个具体指定版本的程序需要知道的事”">​</a></h3><p>在基于 Ubuntu 和 Debian 发行版中，你需要知道一些关于 APT 和存储库是如何工作的知识。</p><h4 id="同一个软件包源没有较旧的版本" tabindex="-1">同一个软件包源没有较旧的版本 <a class="header-anchor" href="#同一个软件包源没有较旧的版本" aria-label="Permalink to “同一个软件包源没有较旧的版本”">​</a></h4><p>Ubuntu 在其存储库中不保留较旧版本的软件包。在特殊的情况下，你可以暂时性地看到多个版本。例如，你运行 APT 更新（但不升级）时，可能会有一个可用的新版本。在 APT 缓存中，你可以看到同一个软件包的两个版本。但是，一旦软件包被升级到了新的版本，较旧版本的软件包将从 <strong>APT 缓存</strong> 和存储库中移除。</p><h4 id="使用多个软件包源来使用不同的版本" tabindex="-1">使用多个软件包源来使用不同的版本 <a class="header-anchor" href="#使用多个软件包源来使用不同的版本" aria-label="Permalink to “使用多个软件包源来使用不同的版本”">​</a></h4>',15)),i("p",null,[s[1]||(s[1]=a("为获取同一个的软件包的多个版本，你必须得添加多个软件包源。例如，VLC 是版本 3.x 系列。添加 ",-1)),n(t,{href:"https://launchpad.net/~videolan/+archive/ubuntu/master-daily"},{default:l(()=>[...s[0]||(s[0]=[a("VLC 每日构建 PPA",-1)])]),_:1}),s[2]||(s[2]=a(" 将会提供（不稳定的）版本 4.x 系列。",-1))]),s[26]||(s[26]=i("p",null,[a("同样，"),i("strong",null,"你可以下载不同版本的 DEB 文件，并安装它"),a("。")],-1)),s[27]||(s[27]=i("h4",{id:"较高版本编号的版本通常有优先权",tabindex:"-1"},[a("较高版本编号的版本通常有优先权 "),i("a",{class:"header-anchor",href:"#较高版本编号的版本通常有优先权","aria-label":"Permalink to “较高版本编号的版本通常有优先权”"},"​")],-1)),s[28]||(s[28]=i("p",null,"如果你有来自多个软件包源的相同名称的软件，默认情况下，Ubuntu 将安装可用的最高版本编号的版本。",-1)),s[29]||(s[29]=i("p",null,"在前面的示例中，如果我安装 VLC ，那么它将会安装 4.x 系列的版本，而不是 3.x 系列的版本。",-1)),s[30]||(s[30]=i("h4",{id:"较旧版本将升级到可用的较新版本",tabindex:"-1"},[a("较旧版本将升级到可用的较新版本 "),i("a",{class:"header-anchor",href:"#较旧版本将升级到可用的较新版本","aria-label":"Permalink to “较旧版本将升级到可用的较新版本”"},"​")],-1)),i("p",null,[s[4]||(s[4]=a("这是另外一个可能存在的问题。即使你安装较旧版本的软件包，它也会升级到较新的版本（如果存在可用的较新版本）。你必须 ",-1)),n(t,{href:"https://itsfoss.com/prevent-package-update-ubuntu/"},{default:l(()=>[...s[3]||(s[3]=[a("保留该软件包来防止其升级",-1)])]),_:1}),s[5]||(s[5]=a(" 。",-1))]),s[31]||(s[31]=e(`<h4 id="依赖关系也需要安装" tabindex="-1">依赖关系也需要安装 <a class="header-anchor" href="#依赖关系也需要安装" aria-label="Permalink to “依赖关系也需要安装”">​</a></h4><p>如果软件包有依赖关系，你也需要安装必要的依赖关系软件包。</p><p>现在，你已经知道一些可能存在的问题，让我们看看如何解决它们。</p><h3 id="安装一个软件包的具体指定版本" tabindex="-1">安装一个软件包的具体指定版本 <a class="header-anchor" href="#安装一个软件包的具体指定版本" aria-label="Permalink to “安装一个软件包的具体指定版本”">​</a></h3><p>在这篇教程中，我将以 VLC 为例。在 Ubuntu 的存储库中可获得 VLC 版本。我添加了每日构建 PPA ，它将向我提供 VLC 的 4.0 版本的候选版本。</p><p>如你所见，在现在的系统中，我有两个可用的 VLC 版本：</p><p><img src="https://itsfoss.com/wp-content/uploads/2022/05/install-specific-versions-apt-ubuntu.png" alt="install specific versions apt ubuntu"></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>~$ apt list -a vlc</span></span>
<span class="line"><span>Listing... Done</span></span>
<span class="line"><span>vlc/jammy 4.0.0~rc1~~git20220516+r92284+296~ubuntu22.04.1 amd64</span></span>
<span class="line"><span>vlc/jammy 3.0.16-1build7 amd64</span></span>
<span class="line"><span>vlc/jammy 3.0.16-1build7 i386</span></span></code></pre></div><p>因为较高版本编号版本有优先权，使用 <code>apt install vlc</code> 命令将会导致安装 VLC 的 4.0 版本。但是，因为这篇教程的缘由，我想安装较旧的版本 3.0.16 。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt install vlc=3.0.16-1build7</span></span></code></pre></div>`,10)),i("p",null,[s[8]||(s[8]=a("但是，这里会有这样的事。VLC 软件包有一些依赖关系，并且这些依赖关系也需要具体指定的版本。因此，在 Ubuntu 为其尝试安装最新的版本时，你将会遇到经典的 ",-1)),i("ruby",null,[n(t,{href:"https://itsfoss.com/held-broken-packages-error/"},{default:l(()=>[...s[6]||(s[6]=[a("你已保留残缺软件包",-1)])]),_:1}),s[7]||(s[7]=i("rt",null,"you have held broken packages",-1))]),s[9]||(s[9]=a(" 错误。",-1))]),s[32]||(s[32]=e(`<p><img src="https://itsfoss.com/wp-content/uploads/2022/05/problem-installing-specific-version-apt-ubuntu-800x365.png" alt="problem installing specific version apt ubuntu"></p><p>为修复这个错误，你需要为其提供它所投诉的所有依赖关系的软件包的具体指定版本。因此，该命令会变成这样：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt install vlc=3.0.16-1build7 \\</span></span>
<span class="line"><span>		 vlc-bin=3.0.16-1build7 \\</span></span>
<span class="line"><span>		 vlc-plugin-base=3.0.16-1build7 \\</span></span>
<span class="line"><span>		 vlc-plugin-qt=3.0.16-1build7 \\</span></span>
<span class="line"><span>		 vlc-plugin-video-output=3.0.16-1build7 \\</span></span>
<span class="line"><span>		 vlc-l10n=3.0.16-1build7 \\</span></span>
<span class="line"><span>		 vlc-plugin-access-extra=3.0.16-1build7 \\</span></span>
<span class="line"><span>		 vlc-plugin-notify=3.0.16-1build7 \\</span></span>
<span class="line"><span>		 vlc-plugin-samba=3.0.16-1build7 \\</span></span>
<span class="line"><span>		 vlc-plugin-skins2=3.0.16-1build7 \\</span></span>
<span class="line"><span>		 vlc-plugin-video-splitter=3.0.16-1build7 \\</span></span>
<span class="line"><span>		 vlc-plugin-visualization=3.0.16-1build7</span></span></code></pre></div><p>说明一下，每行结尾处的 <code>\\</code> 只是用来将多行命令来写入同一个命令的一种方式。</p><p><strong>它有作用吗？在很多情况下，它是有作用的。</strong> 但是，我选择了一个复杂的 VLC 示例，它有很多依赖关系。甚至这些所涉及的依赖关系也依赖于其它的软件包。所以，它就变得令人难以处理。</p><p>一种替代的方法是在安装时指定软件包源。</p><h4 id="替代方式-指定存储库" tabindex="-1">替代方式，指定存储库 <a class="header-anchor" href="#替代方式-指定存储库" aria-label="Permalink to “替代方式，指定存储库”">​</a></h4><p>你已经添加多个软件包源，因此，你应该对这些软件包的来源有一些了解。</p><p>使用下面的命令来搜索存储库：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>apt-cache policy | less</span></span></code></pre></div><p>注意存储库名称后面的行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>500 http://security.ubuntu.com/ubuntu jammy-security/multiverse i386 Packages</span></span>
<span class="line"><span>     release v=22.04,o=Ubuntu,a=jammy-security,n=jammy,l=Ubuntu,c=multiverse,b=i386</span></span>
<span class="line"><span>     origin security.ubuntu.com</span></span></code></pre></div><p>你可以具体指定 <code>o</code>、<code>l</code>、<code>a</code> 等参数。</p><p>在我原来的示例中，我想安装来自 Ubuntu 存储库的 VLC（获取版本 3.16），而不是安装来 PPA 的版本（它将向我提供版本 4）。</p><p>因此，下面的命令将安装 VLC 版本 3.16 及其所有的依赖关系：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt install -t &quot;o=ubuntu&quot; vlc</span></span></code></pre></div><p><img src="https://itsfoss.com/wp-content/uploads/2022/05/install-from-repository-source-800x578.png" alt="install from repository source"></p><p>看起来令人满意？但是，当你必须更新系统时，问题就来了。它接下来会控诉找不到指定的软件包版本。</p><p><strong>还能做什么？</strong></p><p>为安装较旧的软件包版本，从你的系统中移除较新版本的软件包源（如果可能的话）。它将有助于逃脱这些依赖关系地狱。</p><p>如果不能这么做，检查你是否可以从其它一些软件包的打包格式来获取，像 Snap、Flatpak、AppImage 等等。事实上，Snap 和 Flatpak 也允许你从可用的版本中选择和安装。因为这些应用程序是沙盒模式的，所以它很容易管理不同版本的依赖关系。</p><h4 id="保留软件包-防止升级" tabindex="-1">保留软件包，防止升级 <a class="header-anchor" href="#保留软件包-防止升级" aria-label="Permalink to “保留软件包，防止升级”">​</a></h4><p>如果你完成安装一个指定的程序版本，你可能想避免意外地升级到较新的版本。实现这一点并不太复杂。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt-mark hold package_name</span></span></code></pre></div><p>你可以免除保留软件包，以便它能稍后升级：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt-mark unhold package_name</span></span></code></pre></div><p>注意，软件包的依赖关系不会自动地保留。它们需要单独地指明。</p><h3 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to “结论”">​</a></h3><p>如你所见，安装选定软件包版本有一定之规。只有当软件包有依赖关系时，那么事情就会变得复杂，然后，你就会进入依赖关系地狱。</p><p>我希望你在这篇教程中学到一些新的东西。如果你有问题或建议来改善它，请在评论区告诉我。</p><hr>`,31)),i("p",null,[s[11]||(s[11]=a("via: ",-1)),n(t,{href:"https://itsfoss.com/apt-install-specific-version-2/"},{default:l(()=>[...s[10]||(s[10]=[a("https://itsfoss.com/apt-install-specific-version-2/",-1)])]),_:1})]),i("p",null,[s[16]||(s[16]=a("作者：",-1)),n(t,{href:"https://itsfoss.com/author/abhishek/"},{default:l(()=>[...s[12]||(s[12]=[a("Abhishek Prakash",-1)])]),_:1}),s[17]||(s[17]=a(" 选题：",-1)),n(t,{href:"https://github.com/lkxed"},{default:l(()=>[...s[13]||(s[13]=[a("lkxed",-1)])]),_:1}),s[18]||(s[18]=a(" 译者：",-1)),n(t,{href:"https://github.com/robsean"},{default:l(()=>[...s[14]||(s[14]=[a("robsean",-1)])]),_:1}),s[19]||(s[19]=a(" 校对：",-1)),n(t,{href:"https://github.com/wxy"},{default:l(()=>[...s[15]||(s[15]=[a("wxy",-1)])]),_:1})]),i("p",null,[s[22]||(s[22]=a("本文由 ",-1)),n(t,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...s[20]||(s[20]=[a("LCTT",-1)])]),_:1}),s[23]||(s[23]=a(" 原创编译，",-1)),n(t,{href:"https://linux.cn/"},{default:l(()=>[...s[21]||(s[21]=[a("Linux中国",-1)])]),_:1}),s[24]||(s[24]=a(" 荣誉推出",-1))])])}const y=p(d,[["render",h]]);export{C as __pageData,y as default};
